import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
        except StopIteration:
            break

        edges = []
        start_set = set()
        end_set = set()
        next_node = {}

        for _ in range(N - 1):
            u = next(iterator)
            v = next(iterator)
            w = int(next(iterator))

            edges.append((u, v, w))
            start_set.add(u)
            end_set.add(v)
            next_node[u] = (v, w)

        # Find the starting city
        # The starting city is in start_set but not in end_set
        start_city = None
        for city in start_set:
            if city not in end_set:
                start_city = city
                break

        if start_city is None:
            # This case shouldn't happen based on problem description
            continue

        total_cost = 0
        current = start_city
        result_lines = []

        for _ in range(N - 1):
            v, w = next_node[current]
            result_lines.append(f"{current} {v} {w}")
            total_cost += w
            current = v

        for line in result_lines:
            print(line)
        print(total_cost)

if __name__ == "__main__":
    solve()
